#!/usr/bin/env bash
# Connects one scan folder (Samba share) on a Linux Mint / Ubuntu desktop.
# Generated by kodak-s2000w-scan-to-folder/clients/linux/make-client.sh. It CONTAINS the share passwords:
# do not publish it, and delete it from the PC after use.
#
# Usage: bash connect-scans.sh        (as the desktop user, without sudo in front)
#  - User with sudo: mounts via /etc/fstab under /mnt/scans/<Share> (asks for their sudo password).
#  - User without sudo: uses GVFS (like "smb://" in the file manager), reconnects at every login.
set -euo pipefail

SERVER="__SERVER__"
SERVER_IP="__SERVER_IP__"
LABEL="__LABEL__"                   # bookmark name prefix, e.g. "Scans"
declare -A USER_OF=(__USERS__)      # [Share]=samba-user
declare -A PASS_OF=(__PASSWORDS__)  # [Share]=password

[ "$(id -u)" -ne 0 ] || { echo "Run it as the normal desktop user, without sudo."; exit 1; }
DESKTOP_USER="$(id -un)"; DESKTOP_GROUP="$(id -gn)"
mapfile -t SHARES < <(printf '%s\n' "${!USER_OF[@]}" | sort)

# 1. Pick the share
SHARE=""
if [ "${#SHARES[@]}" -eq 1 ]; then
  SHARE="${SHARES[0]}"
elif [ -n "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ] && command -v zenity >/dev/null; then
  args=(); first=TRUE; for s in "${SHARES[@]}"; do args+=("$first" "$s"); first=FALSE; done
  SHARE="$(zenity --list --radiolist --title="Scan folder" --text="Which folder should this PC get?" \
    --column="" --column="Folder" "${args[@]}" --height=260 --width=320 2>/dev/null)" || true
fi
if [ -z "$SHARE" ]; then
  echo "Which folder should this PC get?"
  select s in "${SHARES[@]}"; do [ -n "$s" ] && { SHARE="$s"; break; }; done
fi
[ -n "$SHARE" ] || { echo "No folder chosen."; exit 1; }
SMB_USER="${USER_OF[$SHARE]}"
NAME="$LABEL $SHARE"
if getent hosts "$SERVER" >/dev/null; then HOST="$SERVER"; else HOST="$SERVER_IP"; fi

bookmark() {   # adds "<LABEL> <Share>" to the file manager sidebar
  local f="$HOME/.config/gtk-3.0/bookmarks"
  mkdir -p "$(dirname "$f")"; touch "$f"
  sed -i "\# $NAME\$#d" "$f"
  echo "$1 $NAME" >> "$f"
}

if id -nG "$DESKTOP_USER" | grep -qwE 'sudo|admin|wheel'; then
  # ───────────── With sudo: /etc/fstab ─────────────
  echo "-> Connecting $SHARE for $DESKTOP_USER (system mount; asks for your sudo password)"
  # A broken third-party repository on the PC must not stop the install.
  if ! command -v mount.cifs >/dev/null && [ ! -x /sbin/mount.cifs ]; then
    echo "-> Installing cifs-utils"
    if ! sudo apt-get install -y -qq cifs-utils 2>/dev/null; then
      sudo apt-get update -qq 2>/dev/null || echo "   (warning: a repository on this PC reports errors; continuing)"
      sudo apt-get install -y -qq cifs-utils || true
    fi
    if ! command -v mount.cifs >/dev/null && [ ! -x /sbin/mount.cifs ]; then
      echo "x Could not install cifs-utils. Try by hand: sudo apt-get install cifs-utils"; exit 1
    fi
  fi
  CRED="/etc/scans-${SMB_USER}.cred"
  printf 'username=%s\npassword=%s\n' "$SMB_USER" "${PASS_OF[$SHARE]}" | sudo tee "$CRED" >/dev/null
  sudo chmod 600 "$CRED"; sudo chown root:root "$CRED"
  MOUNT="/mnt/scans/$SHARE"
  sudo mkdir -p "$MOUNT"
  LINE="//$HOST/$SHARE $MOUNT cifs credentials=$CRED,uid=$DESKTOP_USER,gid=$DESKTOP_GROUP,file_mode=0664,dir_mode=0775,vers=3.0,iocharset=utf8,_netdev,nofail,x-systemd.automount,x-systemd.idle-timeout=300,x-systemd.mount-timeout=15 0 0"
  sudo cp /etc/fstab "/etc/fstab.before-scans-$(date +%Y%m%d-%H%M%S)"
  sudo sed -i "\#[[:space:]]$MOUNT[[:space:]]#d" /etc/fstab
  echo "$LINE   # scan folder (kodak-s2000w-scan-to-folder)" | sudo tee -a /etc/fstab >/dev/null
  sudo systemctl daemon-reload
  sudo systemctl restart remote-fs.target 2>/dev/null || true
  if ! ls "$MOUNT" >/dev/null 2>&1; then
    echo "x Could not connect to //$HOST/$SHARE. Check the network and firewall (TCP 445 to the server)"
    echo "  and run the script again. Details: sudo journalctl -n 20 | grep -i cifs"
    exit 1
  fi
  bookmark "file://$MOUNT"
  ln -sfn "$MOUNT" "$HOME/$NAME"
  DESKTOP_DIR="$(xdg-user-dir DESKTOP 2>/dev/null || echo "$HOME/Desktop")"
  [ -d "$DESKTOP_DIR" ] && ln -sfn "$MOUNT" "$DESKTOP_DIR/$NAME"
  echo "OK: \"$NAME\" is in the file manager sidebar, in your home folder and on the desktop."
else
  # ───────────── Without sudo: GVFS ─────────────
  echo "-> Connecting $SHARE for $DESKTOP_USER (no sudo: reconnects at every login)"
  command -v gio >/dev/null || { echo "x gio (gvfs) is missing; someone with sudo must install it."; exit 1; }
  ls /usr/lib/gvfs/gvfsd-smb /usr/libexec/gvfsd-smb /usr/lib/*/gvfs/gvfsd-smb >/dev/null 2>&1 \
    || { echo "x gvfs-backends is missing; someone with sudo must install it."; exit 1; }
  URL="smb://$HOST/$SHARE"
  CONF="$HOME/.config/scans"; mkdir -p "$CONF" "$HOME/.local/bin" "$HOME/.config/autostart"
  ( umask 077; printf '%s\n' "${PASS_OF[$SHARE]}" > "$CONF/password-$SMB_USER" )
  CONNECT="$HOME/.local/bin/scans-connect-$SMB_USER"
  cat > "$CONNECT" <<EOF
#!/usr/bin/env bash
# Connects $URL (scan folder). Run at login.
for i in \$(seq 1 20); do
  gio mount -l 2>/dev/null | grep -qi "$HOST/$SHARE" && exit 0
  printf '%s\nWORKGROUP\n%s\n' "$SMB_USER" "\$(cat "$CONF/password-$SMB_USER")" | gio mount "$URL" >/dev/null 2>&1 && exit 0
  sleep 15
done
exit 1
EOF
  chmod 700 "$CONNECT"
  cat > "$HOME/.config/autostart/scans-$SMB_USER.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=$NAME
Comment=Connects the scan folder
Exec=$CONNECT
X-GNOME-Autostart-enabled=true
NoDisplay=true
EOF
  if ! "$CONNECT"; then
    echo "x Could not connect to $URL. Check the network and firewall (TCP 445 to the server) and run the script again."
    exit 1
  fi
  bookmark "$URL"
  echo "OK: \"$NAME\" is in the file manager sidebar and reconnects at every login."
fi
echo "   New scans show up as PDF about a minute after scanning. Deleted files go to .recycle (30 days)."
